    'cp.v1': 'Virtual DOM · Runtime', 'cp.v2': '~34 KB (vue runtime)', 'cp.v3': 'O(n) diffing + riconciliazione',
    'cp.v4': 'A ogni cambio di stato', 'cp.v5': 'Proxy ES6 + ref/reactive', 'cp.v6': 'Annotazioni manuali',
