    'cp.r9': 'Routing', 'cp.r10': 'Styles', 'cp.r11': 'Lernkurve', 'cp.r12': 'Build-Tool', 'cp.r13': 'Fortsetzbarkeit',
    'cp.a1': 'Zero-VDOM · natives DOM', 'cp.a2': '~3 KB (core)', 'cp.a3': 'O(1) chirurgisch',
